<?php
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(403);exit('CLI only.');}require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$settings=$db->query('SELECT * FROM crm_automation_settings WHERE id=1')->fetch();if(!$settings||!(int)$settings['enabled']){echo "CRM automation disabled.\n";exit;}$log=function(?int $lead,string $type,string $message,string $status='success')use($db){$s=$db->prepare('INSERT INTO automation_logs (lead_id,event_type,message,status) VALUES (?,?,?,?)');$s->execute([$lead,$type,$message,$status]);};
if((int)$settings['auto_score']){$leads=$db->query("SELECT * FROM leads WHERE status NOT IN ('won','lost')")->fetchAll();foreach($leads as $l){$score=0;$reasons=[];$budget=strtolower((string)$l['budget']);$timeline=strtolower((string)$l['timeline']);if($l['service']){$score+=15;$reasons[]='Service selected';}if($l['company']){$score+=10;$reasons[]='Company supplied';}if($l['phone']){$score+=10;$reasons[]='Phone supplied';}if(strlen((string)$l['message'])>=100){$score+=15;$reasons[]='Detailed project brief';}if(preg_match('/urgent|asap|immediately|this week|1 week|2 weeks/i',$timeline)){$score+=20;$reasons[]='Urgent timeline';}if(preg_match('/5000|10000|15000|20000|25000|50000|100000|200000|500000|1000000/i',$budget)){$score+=20;$reasons[]='Higher budget indicated';}if($l['status']==='proposal'){$score+=10;$reasons[]='Proposal stage';}$temperature=$score>=70?'hot':($score>=40?'warm':'cold');$s=$db->prepare('INSERT INTO lead_scores (lead_id,score,temperature,reasons) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE score=VALUES(score),temperature=VALUES(temperature),reasons=VALUES(reasons),calculated_at=CURRENT_TIMESTAMP');$s->execute([(int)$l['id'],$score,$temperature,implode('; ',$reasons)]);$priority=$score>=70?'high':($score>=40?'normal':'low');if($priority!==$l['priority']){$db->prepare('UPDATE leads SET priority=? WHERE id=?')->execute([$priority,$l['id']]);$log((int)$l['id'],'lead_score','Lead scored '.$score.' ('.$temperature.') and priority set to '.$priority);}}}
$now=date('Y-m-d H:i:s');$leads=$db->query("SELECT * FROM leads WHERE status NOT IN ('won','lost') AND follow_up_at IS NULL ORDER BY created_at ASC")->fetchAll();foreach($leads as $l){$created=strtotime((string)$l['created_at']);$hours=(time()-$created)/3600;if($hours >= (int)$settings['initial_followup_hours']){$at=date('Y-m-d H:i:s',time()+((int)$settings['reminder_hours']*3600));$subject='Follow up with '.$l['name'];$body='Follow up with '.$l['name'].' regarding '.$l['service'];$s=$db->prepare("INSERT INTO lead_followups (lead_id,followup_type,scheduled_at,subject,body) VALUES (?, 'initial', ?, ?, ?)");$s->execute([(int)$l['id'],$at,$subject,$body]);$db->prepare('UPDATE leads SET follow_up_at=? WHERE id=?')->execute([$at,$l['id']]);$log((int)$l['id'],'followup_scheduled','Initial follow-up scheduled for '.$at);}}
$due=$db->query("SELECT f.*,l.name,l.email,l.phone,l.service FROM lead_followups f JOIN leads l ON l.id=f.lead_id WHERE f.status='pending' AND f.scheduled_at<=NOW() AND l.status NOT IN ('won','lost') ORDER BY f.scheduled_at ASC LIMIT 100")->fetchAll();foreach($due as $f){$message='Follow-up due for '.$f['name'].' ('.$f['service'].'). Review the lead and contact the client.';$log((int)$f['lead_id'],'followup_due',$message,'warning');$a=$db->prepare('INSERT INTO lead_activities (lead_id,activity_type,subject,description) VALUES (?,?,?,?)');$a->execute([(int)$f['lead_id'],'follow_up','Automated follow-up reminder',$message]);$db->prepare("UPDATE lead_followups SET status='sent',sent_at=NOW() WHERE id=?")->execute([(int)$f['id']]);$db->prepare('UPDATE leads SET follow_up_at=NULL WHERE id=? AND follow_up_at<=NOW()')->execute([(int)$f['lead_id']]);}
echo 'CRM automation completed: '.date('Y-m-d H:i:s')."\n";